<?php require __DIR__.'/config/auth.php';require __DIR__.'/config/database.php';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$pw=$_POST['password']??'';$id=(int)($_SESSION['user']??0);$st=$conn->prepare('SELECT password FROM users WHERE id=?');$st->bind_param('i',$id);$st->execute();$row=$st->get_result()->fetch_assoc();if($row&&password_verify($pw,$row['password'])){$_SESSION=[];session_destroy();header('Location: index.php');exit;}else $err='Password tidak sesuai. Akun belum dikeluarkan.';}?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/css/style.css"><title>Konfirmasi Logout</title></head><body class="auth-page"><section class="auth-card"><h1>Konfirmasi Logout</h1><p class="muted">Masukkan password akun untuk keluar dari SIPN.</p><?php if($err):?><div class="alert"><?=h($err)?></div><?php endif;?><form method="post"><label>Password saat ini</label><input type="password" name="password" required autofocus placeholder="Masukkan password akun"><button class="btn primary full">Keluar</button><a class="btn secondary full" href="index.php">Batal</a></form></section></body></html>